-- Drive Learn - atualizacao multimarcas auditada em 16/10/2026.
-- Execute apos a migracao 030. Nao conecta nem altera a HostGator automaticamente.
-- Produtos futuros/prototipos sao cadastrados inativos; dados nao publicados permanecem em branco.
SET NAMES utf8mb4;
START TRANSACTION;

CREATE TABLE IF NOT EXISTS schema_migrations (versao VARCHAR(80) NOT NULL PRIMARY KEY,descricao VARCHAR(255) NOT NULL,aplicado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS modelo_especificacoes_tecnicas (modelo_id BIGINT UNSIGNED NOT NULL,chave VARCHAR(80) NOT NULL,rotulo VARCHAR(120) NOT NULL,valor VARCHAR(255) NOT NULL,unidade VARCHAR(30) NULL,fonte_url VARCHAR(700) NULL,conferido_em DATE NULL,PRIMARY KEY(modelo_id,chave),INDEX idx_met_chave_031(chave),CONSTRAINT fk_met_modelo_031 FOREIGN KEY(modelo_id) REFERENCES modelos(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- e-Delivery 12
UPDATE modelos m JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id SET m.pbt=CASE WHEN m.pbt IS NULL OR TRIM(m.pbt)='' OR LOWER(TRIM(m.pbt)) IN ('nao informado','não informado','n/d') THEN '12.000 kg' ELSE m.pbt END,m.imagem=CASE WHEN m.imagem IS NULL OR TRIM(m.imagem)='' OR LOWER(TRIM(m.imagem)) IN ('nao informado','não informado','n/d') THEN '/public/assets/images/modelos/vwco-20261016-edelivery-12-17.jpeg' ELSE m.imagem END,m.descricao=CASE WHEN m.descricao IS NULL OR TRIM(m.descricao)='' OR LOWER(TRIM(m.descricao)) IN ('nao informado','não informado','n/d') THEN 'Dados conferidos em fonte publica oficial da fabricante.' ELSE m.descricao END,m.especificacoes=JSON_MERGE_PATCH(COALESCE(m.especificacoes,JSON_OBJECT()),'{"tipo_veiculo":"Caminhao","energia":"100% eletrico","configuracao":"4x2","autonomia":"Ate 250 km","carregamento":"Carga rapida em cerca de 1h30; AC ate 22 kW","mercado":"Distribuicao urbana","situacao_comercial":"Lancado comercialmente em outubro de 2026","observacao_fonte":"Substitui o e-Delivery 11; ficha tecnica completa ainda nao publicada","fonte_oficial":"https://www.prnewswire.com/br/comunicados-para-a-imprensa/vwco-amplia-portfolio-esg-com-novos-veiculos-eletricos-e-a-biometano-302898752.html","fonte_imagem":"https://www.prnewswire.com/br/comunicados-para-a-imprensa/vwco-amplia-portfolio-esg-com-novos-veiculos-eletricos-e-a-biometano-302898752.html","conferido_em":"2026-10-16"}') WHERE ma.slug='volkswagen-caminhoes-onibus' AND (m.slug='e-delivery-12' OR LOWER(TRIM(m.nome))=LOWER(TRIM('e-Delivery 12')));

