INSERT INTO modelos(familia_id,nome,slug,descricao,imagem,motor,potencia,torque,transmissao,pbt,pbtc,relacao_reducao,especificacoes,ativo) SELECT f.id,'e-Delivery 12','e-delivery-12','Dados conferidos em fonte publica oficial da fabricante.','/public/assets/images/modelos/vwco-20261016-edelivery-12-17.jpeg',NULL,NULL,NULL,NULL,'12.000 kg',NULL,NULL,'{"tipo_veiculo":"Caminhao","energia":"100% eletrico","configuracao":"4x2","autonomia":"Ate 250 km","carregamento":"Carga rapida em cerca de 1h30; AC ate 22 kW","mercado":"Distribuicao urbana","situacao_comercial":"Lancado comercialmente em outubro de 2026","observacao_fonte":"Substitui o e-Delivery 11; ficha tecnica completa ainda nao publicada","fonte_oficial":"https://www.prnewswire.com/br/comunicados-para-a-imprensa/vwco-amplia-portfolio-esg-com-novos-veiculos-eletricos-e-a-biometano-302898752.html","fonte_imagem":"https://www.prnewswire.com/br/comunicados-para-a-imprensa/vwco-amplia-portfolio-esg-com-novos-veiculos-eletricos-e-a-biometano-302898752.html","conferido_em":"2026-10-16"}',1 FROM familias f JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='volkswagen-caminhoes-onibus' AND f.nome='e-Delivery' AND NOT EXISTS (SELECT 1 FROM modelos mx JOIN familias fx ON fx.id=mx.familia_id JOIN marcas bx ON bx.id=fx.marca_id WHERE bx.slug='volkswagen-caminhoes-onibus' AND (mx.slug='e-delivery-12' OR LOWER(TRIM(mx.nome))=LOWER(TRIM('e-Delivery 12')))) LIMIT 1;
INSERT INTO modelo_especificacoes_tecnicas(modelo_id,chave,rotulo,valor,unidade,fonte_url,conferido_em) SELECT m.id,'pbt','PBT','12.000 kg',NULL,'https://www.prnewswire.com/br/comunicados-para-a-imprensa/vwco-amplia-portfolio-esg-com-novos-veiculos-eletricos-e-a-biometano-302898752.html','2026-10-16' FROM modelos m JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='volkswagen-caminhoes-onibus' AND m.slug='e-delivery-12' LIMIT 1 ON DUPLICATE KEY UPDATE rotulo=VALUES(rotulo),valor=CASE WHEN valor IS NULL OR TRIM(valor)='' OR LOWER(TRIM(valor)) IN ('nao informado','não informado','n/d') THEN VALUES(valor) ELSE valor END,fonte_url=CASE WHEN valor IS NULL OR TRIM(valor)='' THEN VALUES(fonte_url) ELSE fonte_url END,conferido_em=CASE WHEN valor IS NULL OR TRIM(valor)='' THEN VALUES(conferido_em) ELSE conferido_em END;
