INSERT INTO modelos(familia_id,nome,slug,descricao,imagem,motor,potencia,torque,transmissao,pbt,pbtc,relacao_reducao,especificacoes,ativo) SELECT f.id,'Constellation Ultra 20.500 4x2','constellation-ultra-20-500-4x2','Dados conferidos em fonte publica oficial da fabricante.','/public/assets/images/modelos/vwco-20261016-meteor-ultra.jpeg','MAN D26 Ultra','500 cv',NULL,NULL,NULL,NULL,NULL,'{"tipo_veiculo":"Caminhao","energia":"Diesel","configuracao":"4x2, cavalo mecanico","mercado":"Rodoviario","situacao_comercial":"Anunciado em setembro de 2026; vendas previstas a partir da Fenatran 2026","observacao_fonte":"PBT, PBTC, CMT, reducao e ficha completa ainda nao publicados","fonte_oficial":"https://www.prnewswire.com/br/comunicados-para-a-imprensa/volkswagen-eleva-padrao-de-seus-caminhoes-extrapesados-302874051.html","fonte_imagem":"https://www.prnewswire.com/br/comunicados-para-a-imprensa/volkswagen-eleva-padrao-de-seus-caminhoes-extrapesados-302874051.html","conferido_em":"2026-10-16"}',0 FROM familias f JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='volkswagen-caminhoes-onibus' AND f.nome='Constellation' AND NOT EXISTS (SELECT 1 FROM modelos mx JOIN familias fx ON fx.id=mx.familia_id JOIN marcas bx ON bx.id=fx.marca_id WHERE bx.slug='volkswagen-caminhoes-onibus' AND (mx.slug='constellation-ultra-20-500-4x2' OR LOWER(TRIM(mx.nome))=LOWER(TRIM('Constellation Ultra 20.500 4x2')))) LIMIT 1;
