INSERT INTO modelos(familia_id,nome,slug,descricao,imagem,motor,potencia,torque,transmissao,pbt,pbtc,relacao_reducao,especificacoes,ativo) SELECT f.id,'IVECO Tector NG 160-210','iveco-tector-ng-160-210','Dados conferidos em fonte publica oficial da fabricante.','/public/assets/images/modelos/iveco-20261016-tector-ng.jpg','FPT N60 CNG','210 cv','750 Nm',NULL,'16.000 kg',NULL,NULL,'{"tipo_veiculo":"Caminhao","energia":"GNV / biometano","configuracao":"4x2","autonomia":"Ate 300 km","mercado":"Urbano e regional; predisposicao para bebidas","situacao_comercial":"Produto atual no catalogo brasileiro","observacao_fonte":"A pagina brasileira ainda nao publica a ficha completa para download","fonte_oficial":"https://www.iveco.com/brasil/Tector-natural-gas","fonte_imagem":"https://www.iveco.com/brasil/Tector-natural-gas","conferido_em":"2026-10-16"}',1 FROM familias f JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='iveco' AND f.nome='Tector NG' AND NOT EXISTS (SELECT 1 FROM modelos mx JOIN familias fx ON fx.id=mx.familia_id JOIN marcas bx ON bx.id=fx.marca_id WHERE bx.slug='iveco' AND (mx.slug='iveco-tector-ng-160-210' OR LOWER(TRIM(mx.nome))=LOWER(TRIM('IVECO Tector NG 160-210')))) LIMIT 1;
