INSERT INTO modelos(familia_id,nome,slug,descricao,imagem,motor,potencia,torque,transmissao,pbt,pbtc,relacao_reducao,especificacoes,ativo) SELECT f.id,'BYD T35','byd-t35','Dados conferidos em fonte publica oficial da fabricante.','/public/assets/images/modelos/byd-20261016-t35.webp','Motor eletrico','174 kW (referencia internacional)','340 Nm (referencia internacional)',NULL,'3.300 kg (referencia internacional)',NULL,NULL,'{"tipo_veiculo":"Caminhao","energia":"100% eletrico","configuracao":"4x2, cabine simples","entre_eixos":"3.200","comprimento":"5.515","bateria":"Blade LFP 62,36 kWh (referencia internacional)","autonomia":">= 250 km CLTC-C (referencia internacional)","carregamento":"CCS2 DC 71,7 kW / AC 6,6 kW (referencia internacional)","mercado":"Operacoes comerciais e logisticas","situacao_comercial":"Exibido pela primeira vez no Brasil em agosto de 2026; venda nacional nao confirmada","observacao_fonte":"Dados numericos do folheto global/Equador; confirmar homologacao brasileira antes de ativar","fonte_oficial":"https://www.byd.com/br/BYD-leva-ecossistema-de-mobilidade-e-energia-a-Expointer-2026","fonte_imagem":"https://www.byd.com/br/BYD-leva-ecossistema-de-mobilidade-e-energia-a-Expointer-2026","conferido_em":"2026-10-16","documento_auditoria":"/public/assets/documents/modelos/byd-20261016-t35-referencia-internacional.pdf"}',0 FROM familias f JOIN marcas ma ON ma.id=f.marca_id WHERE ma.slug='byd' AND f.nome='T35' AND NOT EXISTS (SELECT 1 FROM modelos mx JOIN familias fx ON fx.id=mx.familia_id JOIN marcas bx ON bx.id=fx.marca_id WHERE bx.slug='byd' AND (mx.slug='byd-t35' OR LOWER(TRIM(mx.nome))=LOWER(TRIM('BYD T35')))) LIMIT 1;
